void init_SdaiClassified_item( Registry& reg ) {
    std::string str;
        config_control_design::t_classified_item = new SelectTypeDescriptor (
                  ~(sdaiINSTANCE),        //unique elements,
                  "Classified_Item",        // Name
                  sdaiSELECT,        // FundamentalType
                  config_control_design::schema,        // Originating Schema
                  "SELECT (Product_Definition_Formation, Assembly_Component_Usage)",        // Description
                  (SelectCreator) create_SdaiClassified_item);        // Creator function
        config_control_design::schema->AddType(config_control_design::t_classified_item);
    config_control_design::t_classified_item -> Elements ().AddNode (config_control_design::e_product_definition_formation);
    config_control_design::t_classified_item -> Elements ().AddNode (config_control_design::e_assembly_component_usage);
    reg.AddType (*config_control_design::t_classified_item);
}

